const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.box}"/></svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,act,ico='',cls='',attrs='')=>`<button class="button ${cls}" data-act="${act}" ${attrs}>${ico?icon(ico):''}${label}</button>`;
const chip=(label,color='')=>`<span class="chip ${color}"><i></i>${label}</span>`;
const empty=(title,text='',act='')=>`<div class="empty">${icon('layers')}<h3>${title}</h3><p>${text}</p>${act}</div>`;
const formatTime=s=>new Date(s).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false});
const statusMap={queued:['排队中','blue'],running:['模拟运行中','purple'],collecting:['收集产物','purple'],done:['已完成','green'],failed:['运行失败','red'],cancelled:['已取消',''],interrupted:['已中断','amber']};
const verdictMap={pass:['通过','green'],fail:['不通过','red'],review:['待复核','amber']};
const runStatus=r=>chip(...(statusMap[r.status]||['未运行','']));
const verdict=v=>v?chip(...verdictMap[v]):'<span class="muted">—</span>';
const field=(label,control,hint='',cls='')=>`<div class="field ${cls}"><label>${label}</label>${control}${hint?`<small>${hint}</small>`:''}</div>`;
const note=(text,type='')=>`<div class="note ${type}">${icon('info')}<span>${text}</span></div>`;
const categoryPath=model=>modelClassification(model).join(' / ');
const mountKindName=kind=>mountKinds.find(item=>item.id===kind)?.name||'挂载';
const mountItemName=kind=>mountKinds.find(item=>item.id===kind)?.itemName||'实体';
const mountOptionLabel=kind=>kind.id==='ammo'?'直接挂载武器':`${kind.name}（挂载${kind.itemName}）`;
const weaponModels=(plan,parentId)=>{const groups=new Map();for(const entity of mountedWeaponEntities(plan,parentId)){const entry=groups.get(entity.model.id)||{model:entity.model,count:0};entry.count++;groups.set(entity.model.id,entry);}return [...groups.values()];};
const modelCard=m=>`<div class="panel model-card"><div class="row between">${chip(esc(m.FirstCfn||'未分类'),'purple')}<span class="mono muted">型号 ${esc(m.id)}</span></div><div class="model-visual">${icon('plane')}</div><h3>${esc(m.mxmc)}</h3><span class="mono muted" style="font-size:10px">${esc(m.mxnm)}</span><p>${esc(m.description||'可用于地图实体或挂载实体。')}</p><div class="model-meta"><span>${esc(modelClassification(m).slice(1).join(' / '))}</span><button class="text-button" data-act="model-detail" data-id="${esc(m.id)}" style="font-size:10px">配置 ${icon('arrow')}</button></div></div>`;
function modelCatalog(){const groups=new Map();for(const model of db.models){const path=categoryPath(model);if(!groups.has(path))groups.set(path,[]);groups.get(path).push(model);}return [...groups].map(([path,list])=>`<section class="classification-group"><div class="classification-heading"><div><span class="eyebrow">装备分类</span><h2>${esc(path)}</h2></div>${chip(`${list.length} 个型号`,'')}</div><div class="library-grid">${list.map(modelCard).join('')}</div></section>`).join('')+`<button class="panel model-card add-model-card" data-act="add-model">${icon('plus')}<h3 style="margin-top:15px">添加一个型号</h3><p>填写四级分类、型号与编码后<br>即可在想定编辑中按分类选择</p></button>`;}
const app=document.querySelector('#app');
let db=api.snapshot();
const ui={filter:'all',query:'',selected:new Set(),draft:null,dirty:false,entity:null,placement:null,fileTab:'scenario',runFilter:'all',resultTab:'overview',libraryTab:'models',evidence:null};
let modalCleanup=null;
let acceptedHash=location.hash;
function route(){const [page='plans',id,tab]=location.hash.replace(/^#\/?/,'').split('/');return {page,id,tab};}
function go(path){if(ui.dirty&&route().page==='plan'&&path.split('/')[1]!==ui.draft?.id){confirmLeave(path);return;}location.hash='/'+path;}
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.innerHTML=icon(error?'alert':'circle')+`<span>${esc(message)}</span>`;document.querySelector('#toasts').append(el);setTimeout(()=>el.remove(),4200);}
function showModal(title,subtitle,body,footer='',wide=false){closeModal();document.querySelector('#modal-root').innerHTML=`<div class="overlay"><section role="dialog" aria-modal="true" aria-labelledby="modal-title" class="modal ${wide?'wide':''}"><div class="modal-header"><div><h2 id="modal-title">${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="icon-button" data-act="close" aria-label="关闭弹窗">${icon('close')}</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-footer">${footer}</div>`:''}</section></div>`;setTimeout(()=>document.querySelector('.modal input:not([type=checkbox]):not([type=radio]),.modal select,.modal button')?.focus(),30);}
function closeModal(){modalCleanup?.();modalCleanup=null;document.querySelector('#modal-root').innerHTML='';}
function modalError(message){const body=document.querySelector('.modal-body');body.querySelector('.inline-error')?.remove();body.insertAdjacentHTML('afterbegin',`<div class="inline-error" role="alert">${esc(message)}</div>`);body.scrollTop=0;}
function jsonHTML(obj){return esc(JSON.stringify(obj,null,2)).replace(/(&quot;.*?&quot;)(\s*:)?|\b(true|false|null|\d+(?:\.\d+)?)\b/g,(m,s,k,n)=>s?`<span class="${k?'code-key':'code-string'}">${s}</span>${k||''}`:`<span class="code-number">${n}</span>`);}
function download(value,name,type='application/json'){const blob=value instanceof Uint8Array?new Blob([value],{type}):new Blob([typeof value==='string'?value:JSON.stringify(value,null,2)],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function touch(){ui.draft.revision++;ui.draft.updated=new Date().toISOString();ui.dirty=true;}
async function saveDraft(){if(!ui.draft)return;ui.draft=await api.savePlan(ui.draft);ui.dirty=false;render();if(api.snapshot().storageError)toast('浏览器存储已满，当前修改仅保存在内存，请导出方案。',true);}
function planState(p){const errors=validate(p).errors;if(!p.entities.length)return chip('草稿','');if(errors.length)return chip('待修正','amber');if(p.generated?.revision===p.revision)return chip('已生成','green');return chip('待生成','purple');}

function shell(){
  const r=route(),active=r.page==='plan'?'plans':r.page==='run'?'runs':r.page;
  const labels={plans:'方案管理',runs:'运行中心',library:'模型与行动',settings:'设置'};
  return `<aside class="sidebar"><a class="brand" href="#/plans"><div class="brand-logo">${icon('logo')}</div><div><div class="brand-name">SimTest<span style="color:#a08cde">.</span></div><div class="brand-sub">仿真测试工作台</div></div></a><div class="workspace"><span class="workspace-symbol">${icon('layers')}</span><div class="grow"><b>仿真验证工作空间</b><small>个人工作区</small></div>${icon('down')}</div><div class="nav-label">WORKSPACE</div><nav class="nav">${[['plans','grid','方案管理'],['runs','play','运行中心'],['library','box','模型与行动'],['settings','settings','设置']].map(([id,ic,label])=>`<a href="#/${id}" data-nav="${id}" class="${active===id?'active':''}">${icon(ic)}<span>${label}</span>${id==='runs'&&db.runs.some(r=>r.status==='queued'||r.status==='running')?'<span class="count">运行中</span>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="demo-card"><div class="row">${icon('bolt')} 前端交互 Demo</div><p>型号与行动类型存入数据库<br>方案保存在当前浏览器</p><button class="text-button" data-act="help">了解演示范围 ${icon('arrow')}</button></div><div class="profile"><div class="avatar">工</div><div class="grow"><strong>仿真工程师</strong><small>本地工作空间</small></div><span class="live-dot"></span></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumb">工作台 ${icon('chevron')} <span class="current">${labels[active]||'方案管理'}</span>${r.page==='plan'||r.page==='run'?`${icon('chevron')}<span class="current">${r.page==='plan'?'方案编辑':'运行详情'}</span>`:''}</div><div class="top-actions"><span class="mode-pill"><i></i> ${db.catalogMode==='backend'?'装备数据库已连接':'装备目录本地模式'}</span><span class="small muted">模拟运行</span><button class="icon-button" data-act="help" aria-label="使用帮助">${icon('help')}</button><span class="small muted">V 0.2</span></div></header>${db.storageError?'<div class="storage-warning">浏览器存储空间不足，修改仅保存在内存，请导出重要数据。</div>':''}${db.catalogError?`<div class="storage-warning">装备数据库提示：${esc(db.catalogError)}</div>`:''}${db.actionCatalogError?`<div class="storage-warning">行动目录暂不可用：${esc(db.actionCatalogError)}</div>`:''}<div class="content" id="content"></div></main>`;
}
function stats(items){return `<div class="stats">${items.map(([title,value,info,ic,color])=>`<div class="stat"><div class="stat-title">${title}<span class="stat-icon ${color||''}">${icon(ic)}</span></div><div class="stat-value">${String(value).padStart(2,'0')}</div><div class="stat-note">${info}</div></div>`).join('')}</div>`;}
function plansPage(){
  const ps=db.plans.filter(p=>!p.archived),ready=ps.filter(p=>!validate(p).errors.length),bad=ps.filter(p=>p.entities.length&&validate(p).errors.length);
  return `<div class="page-heading"><div><div class="eyebrow">SIMULATION WORKSPACE</div><h1>方案管理</h1><p>从一个想定开始，让每一次仿真都有据可循。</p></div><div class="row">${button('从示例创建','example','copy')}${button('新建方案','new','plus','primary')}</div></div>${stats([['全部方案',ps.length,'<strong>本地工作空间</strong> · 持续保存','file'],['可运行方案',ready.length,'实体、行动与资源校验通过','circle','green'],['待修正方案',bad.length,'查看校验提示，完善方案配置','alert','amber'],['运行记录',db.runs.length,'全部为前端模拟执行记录','play','blue']])}<div class="dashboard-grid"><div class="panel"><div class="panel-heading"><h2>我的方案 <span class="panel-title-count">${ps.length}</span></h2><button class="text-button" data-act="refresh">${icon('refresh')} 刷新</button></div><div class="tabs">${[['all','全部方案'],['ready','可运行'],['draft','草稿 / 待修正'],['archive','已归档']].map(([key,name])=>`<button data-act="filter" data-value="${key}" class="${ui.filter===key?'active':''}">${name}</button>`).join('')}</div><div class="table-toolbar"><div class="searchbox">${icon('search')}<input id="plan-search" placeholder="搜索方案名称…" aria-label="搜索方案名称" value="${esc(ui.query)}"></div>${button(ui.selected.size?`批量运行 · ${ui.selected.size}`:'批量运行','batch','play','small',ui.selected.size?'':'disabled')}</div><div class="table-scroll"><table><thead><tr><th style="width:35px"><input type="checkbox" id="select-all" aria-label="选择全部可见方案"></th><th>方案名称</th><th>实体 / 行动</th><th>状态</th><th>最近更新</th><th style="text-align:right">操作</th></tr></thead><tbody id="plan-rows">${planRows()}</tbody></table></div><div class="table-foot"><span>共 ${filteredPlans().length} 个方案 · 数据自动保留在本机</span><div class="mini-numbers">${icon('back')}<span>1</span>${icon('chevron')}</div></div></div><aside class="dashboard-aside"><div class="panel"><div class="guide-top"><div class="guide-orb"></div><h3>开始一次仿真</h3><p>把配置、执行与结果<br>连接成一个清晰的流程。</p></div><div class="steps">${[['构建想定','地图布点，配置实体与挂载'],['编排行动','选择执行者、目标与时间'],['运行与判读','检查事件，复盘运行结果']].map(([t,p],i)=>`<div class="guide-step"><span class="step-circle">${i+1}</span><div><b>${t}</b><p>${p}</p></div></div>`).join('')}</div><div class="guide-footer"><button class="text-button" data-act="example">用示例开始 ${icon('arrow')}</button></div></div><div class="panel info-card"><h3>${icon('layers')} 配置驱动，自由扩展</h3><p>模型与行动独立管理。新模型加载后，即可在想定中选择使用。</p><button class="text-button" data-act="library">查看模型与行动 ${icon('arrow')}</button></div></aside></div><div class="panel recent-panel"><div class="panel-heading"><h3>工作空间动态</h3><span class="small muted">本地记录</span></div><div class="recent-grid">${db.runs.length?db.runs.slice(0,3).map(r=>`<button class="recent-item" data-act="run-detail" data-id="${r.id}">${icon('play')}<div><b>${esc(r.plan.name)} · ${statusMap[r.status][0]}</b><p>${formatTime(r.created)} · 模拟执行</p></div></button>`).join(''):`<div class="recent-item">${icon('box')}<div><b>示例模型目录已加载</b><p>按四级分类创建地图及挂载实体</p></div></div><div class="recent-item">${icon('file')}<div><b>示例方案已准备</b><p>可直接编辑、校验和生成文件</p></div></div><div class="recent-item">${icon('monitor')}<div><b>模拟运行环境就绪</b><p>无需连接外部仿真程序</p></div></div>`}</div></div><footer class="footer"><span>SimTest · 把每一次验证，变成可追溯的结果。</span><span>本地保存 ${icon('check')} &nbsp; 前端 Demo v0.1</span></footer>`;
}
function filteredPlans(){return db.plans.filter(p=>(ui.filter==='archive'?p.archived:!p.archived)&&p.name.toLowerCase().includes(ui.query.toLowerCase())&&(ui.filter==='ready'?!validate(p).errors.length:ui.filter==='draft'?validate(p).errors.length:true));}
function planRows(){const list=filteredPlans();return list.length?list.map(p=>`<tr><td><input type="checkbox" data-select="${p.id}" aria-label="选择 ${esc(p.name)}" ${ui.selected.has(p.id)?'checked':''}></td><td><div class="plan-title"><span class="plan-glyph">${icon('file')}</span><button data-act="edit-plan" data-id="${p.id}"><b>${esc(p.name)}</b><small>SIM-${p.id.slice(-6).toUpperCase()} · ${Math.round(duration(p)/60)} 分钟</small></button></div></td><td>${p.entities.length} 实体 <span style="color:#d1d5df">/</span> ${p.actions.length} 行动</td><td>${planState(p)}</td><td>${formatTime(p.updated)}</td><td><div class="row" style="justify-content:flex-end;gap:1px"><button class="icon-button" title="编辑方案" aria-label="编辑 ${esc(p.name)}" data-act="edit-plan" data-id="${p.id}">${icon('edit')}</button><button class="icon-button" title="复制方案" aria-label="复制 ${esc(p.name)}" data-act="copy-plan" data-id="${p.id}">${icon('copy')}</button><button class="icon-button" title="${p.archived?'恢复方案':'归档方案'}" aria-label="${p.archived?'恢复':'归档'} ${esc(p.name)}" data-act="archive" data-id="${p.id}">${icon(p.archived?'refresh':'archive')}</button></div></td></tr>`).join(''):`<tr><td colspan="6">${empty('没有符合条件的方案','调整搜索条件，或新建一个方案。')}</td></tr>`;}

function planPage(r){
  if(ui.draft?.id!==r.id){ui.draft=clone(db.plans.find(p=>p.id===r.id));ui.dirty=false;ui.entity=ui.draft?.entities[0]?.id;ui.placement=null;}
  const p=ui.draft;if(!p)return empty('方案不存在','返回方案管理，选择已有方案。',button('返回方案管理','plans','back'));
  const tab=r.tab||'map',check=validate(p);
  return `<div class="page-heading editor-heading"><div><button class="back-link" data-act="plans">${icon('back')} 返回方案管理</button><h1>${esc(p.name)}</h1><p>修订 ${p.revision} <span style="margin:0 8px;color:#d5d7e0">|</span> ${ui.dirty?'有未保存的修改':'已保存至本地'} <span style="margin-left:8px">${planState(p)}</span></p></div><div class="row">${button('保存','save','save')}${button('生成文件','generate','code')}${button('模拟运行','run-current','play','primary')}</div></div><div class="tabs editor-tabs">${[['info','file','基本信息'],['map','map','想定编辑'],['actions','bolt','行动指令'],['files','code','生成与校验']].map(([key,ic,name])=>`<button data-act="editor-tab" data-value="${key}" class="${tab===key?'active':''}">${icon(ic)}${name}${key==='actions'?` <span class="panel-title-count">${p.actions.length}</span>`:''}</button>`).join('')}</div><div class="editor-body">${tab==='info'?infoTab(p):tab==='actions'?actionsTab(p):tab==='files'?filesTab(p):mapTab(p)}</div><div style="margin-top:17px">${check.errors.length?note(`<button class="text-button" data-act="editor-tab" data-value="files">${check.errors.length} 项需要修正</button> · ${esc(check.errors[0].message)}`,'warning'):note('结构与引用检查通过。可以生成配套文件，或进入模拟运行。','success')}</div>`;
}
function infoTab(p){return `<div class="editor-info"><div class="form-section"><h3>方案基本信息</h3><div class="form-grid">${field('方案名称 <span class="required">*</span>',`<input data-plan="name" aria-label="方案名称" maxlength="60" value="${esc(p.name)}">`,'便于区分用途，生成标题会自动附加唯一编号。','full')}${field('方案说明',`<textarea rows="3" data-plan="description" aria-label="方案说明" placeholder="记录这次仿真的目的…">${esc(p.description)}</textarea>`,'','full')}${field('仿真开始时间',`<input type="datetime-local" step="1" data-plan="start" aria-label="仿真开始时间" value="${p.start.replace(' ','T')}">`)}${field('仿真结束时间',`<input type="datetime-local" step="1" data-plan="end" aria-label="仿真结束时间" value="${p.end.replace(' ','T')}">`)}</div></div>${note(`当前仿真时长 <b>${Number.isFinite(duration(p))?duration(p):'—'} 秒</b>。行动时间从仿真开始的第 0 秒计算。`)}<div style="margin-top:24px">${button('前往想定编辑','editor-tab','arrow','primary','data-value="map"')}</div></div>`;}
function mapTab(p){const selected=p.entities.find(e=>e.id===ui.entity),roots=deployedEntities(p),mounts=p.entities.filter(e=>e.parentId);return `<div class="map-editor"><div class="entity-list"><div class="row between"><h3>实体列表 <span class="muted">${roots.length} 主体 · ${mounts.length} 挂载</span></h3></div>${button(ui.placement?'结束布置':'添加实体',ui.placement?'stop-place':'add-entity',ui.placement?'close':'plus','soft small','style="width:100%"')}${['Blue','Red'].map(side=>`<div class="side-title"><span><i class="side-dot ${side==='Red'?'red':'blue'}"></i> ${side==='Blue'?'蓝方':'红方'}</span><span>${roots.filter(e=>e.side===side).length}</span></div>${roots.filter(e=>e.side===side).map(e=>`<button class="entity-item ${e.id===ui.entity?'active':''}" data-act="select-entity" data-id="${e.id}">${icon('plane')}<span><b>${esc(e.name)}</b><small>${e.bzlx?'编队':'普通实体'} · ${e.height} m</small></span></button>${mountedEntities(p,e.id).map(child=>`<button class="entity-item mount-item ${child.id===ui.entity?'active':''}" data-act="select-entity" data-id="${child.id}">${icon('box')}<span><b>${esc(child.name)}</b><small>${mountKindName(child.mountKind)} · ${mountItemName(child.mountKind)}实体</small></span></button>`).join('')}`).join('')}`).join('')}${!roots.length?'<p class="small muted" style="padding:20px 6px;line-height:1.9">添加地图实体后，可继续为它添加挂载实体。</p>':''}</div><div id="scenario-map" class="map-stage ${ui.placement?'placing':''}"></div><div class="entity-props">${selected?entityProps(p,selected):empty('选择一个实体','在地图或列表中选择实体，编辑属性。')}</div></div><div class="editor-foot"><span class="row">${icon('info')} ${ui.placement?`批量布置：${esc(ui.placement.model.mxmc)} · ${ui.placement.quantity} 个${ui.placement.formation?'编队':'普通实体'} · 点击地图选择中心位置`:'主实体可在地图移动 · 挂载实体跟随所属主实体'}</span><span>${roots.length} 个地图实体 · ${mounts.length} 个挂载实体</span></div>`;}
function entityProps(p,e){const mounted=!!e.parentId,formation=!!e.bzlx?.trim(),parent=mounted?p.entities.find(item=>item.id===e.parentId):null,children=mounted?[]:mountedEntities(p,e.id);let groups=[];if(!mounted){const map=new Map();for(const child of children){const key=`${child.mountKind}:${child.model.id}`,entry=map.get(key)||{kind:child.mountKind,model:child.model,count:0,id:child.id};entry.count++;map.set(key,entry);}groups=[...map.values()];}return `<div class="row between" style="margin-bottom:17px"><h3 style="margin:0">实体属性</h3><button class="icon-button" data-act="delete-entity" data-id="${e.id}" title="删除实体" aria-label="删除当前实体">${icon('trash')}</button></div><div class="form-grid">${field('实体名称',`<input data-entity-field="name" aria-label="实体名称" value="${esc(e.name)}">`,'','full')}${field('阵营',mounted?`<input disabled value="${e.side==='Blue'?'蓝方':'红方'}">`:`<select data-entity-field="side" aria-label="实体阵营"><option value="Blue" ${e.side==='Blue'?'selected':''}>蓝方</option><option value="Red" ${e.side==='Red'?'selected':''}>红方</option></select>`)}${field('实体类型',`<input disabled value="${mounted?'挂载实体':formation?'编队':'普通实体'}">`)}${field('模型',`<input disabled value="${esc(e.model.mxmc)}">`,'','full')}${field('分类',`<input disabled value="${esc(categoryPath(e.model))}">`,'','full')}${mounted?field('所属主实体',`<input disabled value="${esc(parent?.name||'主实体缺失')}">`,'','full')+field('挂载关系',`<input disabled value="${mountKindName(e.mountKind)}（${mountItemName(e.mountKind)}）">`,'','full'):field('经度',`<input type="number" step=".0001" data-entity-field="lon" aria-label="实体经度" value="${e.lon}">`)+field('纬度',`<input type="number" step=".0001" data-entity-field="lat" aria-label="实体纬度" value="${e.lat}">`)+field('高度 / m',`<input type="number" data-entity-field="height" aria-label="实体高度" value="${e.height}">`,'','full')}</div>${mounted?'':`<div class="property-divider"><div class="row between" style="margin-bottom:10px"><h3 style="margin:0">挂载实体</h3>${button('添加挂载','add-mount','plus','soft small',`data-id="${e.id}"`)}</div>${groups.length?groups.map(group=>`<button class="inventory" data-act="select-entity" data-id="${group.id}" style="width:100%;text-align:left"><div><b>${esc(group.model.mxmc)}</b><small>${mountKindName(group.kind)} · ${mountItemName(group.kind)}实体</small></div><b>× ${group.count}</b></button>`).join(''):'<p class="small muted" style="font-size:10px;line-height:1.8;padding:8px 0">暂无挂载。点击“添加挂载”，通过分类选择飞机或武器模型。</p>'}</div>`}<details style="margin-top:19px;color:#969db0;font-size:10px"><summary style="cursor:pointer">实例信息</summary><p class="mono" style="overflow-wrap:anywhere;line-height:1.8;margin-top:10px;font-size:9px">模型编码：${esc(e.model.mxnm)}<br>${mounted?'资源编号':formation?'编队编号':'资源编号'}：${entityId(e)}</p></details>`;}
function actionsTab(p){
  return `<div class="action-summary"><div class="grow"><h3>行动编排 <span class="panel-title-count">${p.actions.length}</span></h3><p>按执行实体展开，每条行动拥有独立的指令编号。</p></div>${button('添加行动','add-action','plus','primary small')}</div>${p.actions.length?`<div class="table-scroll"><table><thead><tr><th>行动 / 代码</th><th>执行实体</th><th>目标实体</th><th>时间窗口 / s</th><th>武器使用</th><th>操作</th></tr></thead><tbody>${p.actions.map(a=>{const e=deployedEntities(p).find(e=>e.id===a.executor),weapon=mountedWeaponEntities(p,a.executor).find(item=>item.model.id===a.weaponModelId)?.model;return `<tr><td><b style="font-weight:500;color:#5f6a80">${esc(a.name)}</b><div class="mono muted" style="font-size:10px;margin-top:7px">${a.code}</div></td><td><i class="side-dot ${e?.side==='Red'?'red':'blue'}"></i> ${esc(e?.name||'实体缺失')}</td><td>${a.targets.map(t=>esc(deployedEntities(p).find(e=>e.id===t)?.name||'目标缺失')).join('、')||(a.definition&&!a.definition.target?'<span class="muted">未启用</span>':'<span class="text-red">未选择</span>')}</td><td>${a.start} — ${a.end}<div class="time-bar"><i style="left:${Math.max(0,Math.min(100,a.start/duration(p)*100))}%;width:${Math.max(3,Math.min(100,(a.end-a.start)/duration(p)*100))}%"></i></div></td><td>${a.weapon?`${esc(a.definition?'武器合计':weapon?.mxmc||'武器实体')} <b style="margin-left:4px">× ${a.count}</b>`:'<span class="muted">未启用</span>'}</td><td><button class="icon-button" data-act="edit-action" data-id="${a.id}" aria-label="编辑行动" title="编辑行动">${icon('edit')}</button><button class="icon-button" data-act="copy-action" data-id="${a.id}" aria-label="复制行动" title="复制行动">${icon('copy')}</button><button class="icon-button" data-act="delete-action" data-id="${a.id}" aria-label="删除行动" title="删除行动">${icon('trash')}</button></td></tr>`;}).join('')}</tbody></table></div>`:empty('添加第一条行动','选择执行实体、目标与时间，系统自动维护指令引用。',button('添加行动','add-action','plus','primary'))}<div style="padding:22px">${note('行动类型和必填字段来自行动目录；可在模型与行动页面配置。模拟事件与真实仿真判据独立，未配置真实规则时结论应为待复核。')}</div>`;
}
function filesTab(p){
  const check=validate(p),valid=p.generated?.revision===p.revision,roots=deployedEntities(p),mounts=p.entities.length-roots.length,formations=roots.filter(e=>e.bzlx?.trim()).length,ordinary=roots.length-formations,executors=new Set(p.actions.map(a=>a.executor)).size,targets=new Set(p.actions.flatMap(a=>a.targets)).size;
  return `<div class="validation-layout"><div class="validation-panel"><h3 style="margin-bottom:9px">生成前检查</h3><p class="small muted" style="line-height:1.8;margin-bottom:16px">基于当前方案的实体、引用、库存与时间。</p>${check.errors.length?chip(`${check.errors.length} 项错误`,'red'):chip('校验通过','green')}${check.errors.map(e=>`<button class="check-item text-red" data-act="locate-error" data-tab="${e.tab}" data-id="${e.entity||''}">${icon('alert')}<span>${esc(e.message)}</span></button>`).join('')}${!check.errors.length?['实体与行动 ID 唯一','执行者与目标引用有效','武器类型及累计数量正确','行动时间位于仿真范围'].map(t=>`<div class="check-item text-green">${icon('circle')}<span>${t}</span></div>`).join(''):''}${check.warnings.map(e=>`<div class="check-item" style="color:#ac9466">${icon('info')}<span>${esc(e.message)}</span></div>`).join('')}<div style="margin-top:22px">${button('生成配套文件','generate','code','primary small',check.errors.length?'disabled':'')}</div></div><div class="code-panel"><div class="code-toolbar"><div class="segmented"><button data-act="file-tab" data-value="scenario" class="${ui.fileTab==='scenario'?'active':''}">想定文件摘要</button><button data-act="file-tab" data-value="commands" class="${ui.fileTab==='commands'?'active':''}">指令文件摘要</button></div>${button('导出配套 ZIP','export-pair','download','small',valid?'':'disabled')}</div>${valid?`<p class="mono muted" style="font-size:10px;margin-bottom:18px;overflow-wrap:anywhere">${ui.fileTab==='scenario'?db.settings.scenarioRoot:db.settings.commandRoot}/${esc(p.generated.ybnm)}.json</p>${ui.fileTab==='scenario'?`<div class="summary-grid"><div class="summary-cell"><label>方案标题</label><b>${esc(p.generated.ybnm)}</b></div><div class="summary-cell"><label>仿真时段</label><b>${esc(p.start)} 至 ${esc(p.end)}</b></div><div class="summary-cell"><label>阵营数量</label><b>2</b></div><div class="summary-cell"><label>地图实体</label><b>${roots.length}</b></div><div class="summary-cell"><label>挂载实体</label><b>${mounts}</b></div><div class="summary-cell"><label>编队 / 普通实体</label><b>${formations} / ${ordinary}</b></div></div>`:`<div class="summary-grid"><div class="summary-cell"><label>方案标题</label><b>${esc(p.generated.ybnm)}</b></div><div class="summary-cell"><label>行动数量</label><b>${p.actions.length}</b></div><div class="summary-cell"><label>行动组数量</label><b>${executors}</b></div><div class="summary-cell"><label>执行实体</label><b>${executors}</b></div><div class="summary-cell"><label>目标实体</label><b>${targets}</b></div><div class="summary-cell"><label>方案修订</label><b>${p.revision}</b></div></div>`}<div class="row between" style="margin-top:18px"><span class="small muted">UTF-8 · 严格 JSON · 修订 ${p.revision}</span><button class="text-button" data-act="export-file">${icon('download')} 导出当前文件</button></div>`:empty(p.generated?'方案已修改，请重新生成':'还没有生成文件','校验通过后生成想定与指令。两份文件名称一致，分别保存在不同目录。')}</div></div>`;
}
function runsPage(){const list=db.runs.filter(r=>ui.runFilter==='all'||ui.runFilter==='active'?ui.runFilter==='all'||['queued','running','collecting'].includes(r.status):ui.runFilter==='done'?r.status==='done':['failed','cancelled','interrupted'].includes(r.status));return `<div class="page-heading"><div><div class="eyebrow">EXECUTION CENTER</div><h1>运行中心</h1><p>跟踪每次执行，保留输入、产物与判读证据。</p></div>${button('选择方案运行','plans','plus','primary')}</div>${stats([['累计运行',db.runs.length,'前端模拟记录','play'],['执行中 / 排队',db.runs.filter(r=>['queued','running','collecting'].includes(r.status)).length,'串行队列 · 并发数 1','clock','blue'],['运行完成',db.runs.filter(r=>r.status==='done').length,'完成不等于行动通过','circle','green'],['异常 / 中断',db.runs.filter(r=>['failed','interrupted'].includes(r.status)).length,'可查看日志并重新运行','alert','amber']])}<div class="page-note">${note('当前为模拟运行：进度、事件和产物由前端生成，未调用实际仿真器。')}</div><div class="panel"><div class="panel-heading"><h2>运行记录</h2><span class="small muted">最新提交在前</span></div><div class="tabs">${[['all','全部'],['active','运行中 / 排队'],['done','已完成'],['error','异常 / 已取消']].map(([k,v])=>`<button class="${ui.runFilter===k?'active':''}" data-act="run-filter" data-value="${k}">${v}</button>`).join('')}</div>${list.length?`<div class="table-scroll"><table><thead><tr><th>方案 / 运行编号</th><th>运行状态</th><th>判读结论</th><th>提交时间</th><th>操作</th></tr></thead><tbody>${list.map(r=>`<tr><td><div class="plan-title"><span class="plan-glyph">${icon('play')}</span><button data-act="run-detail" data-id="${r.id}"><b>${esc(r.plan.name)}</b><small class="mono">RUN-${r.id.slice(-8).toUpperCase()}</small></button></div></td><td>${runStatus(r)}${['running','collecting'].includes(r.status)?`<div class="run-progress"><i style="width:${r.progress}%"></i></div>`:''}</td><td>${verdict(r.verdict)}</td><td>${formatTime(r.created)}</td><td><button class="text-button" data-act="run-detail" data-id="${r.id}">查看详情 ${icon('chevron')}</button>${['queued','running','collecting'].includes(r.status)?`<button class="icon-button" data-act="cancel-run" data-id="${r.id}" title="取消模拟运行" aria-label="取消模拟运行">${icon('stop')}</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:empty('还没有运行记录','从方案管理选择一个方案，开始第一次模拟运行。',button('前往方案管理','plans','arrow','primary'))}</div>`;}
function runPage(id){const r=db.runs.find(r=>r.id===id);if(!r)return empty('运行记录不存在');const active=['queued','running','collecting'].includes(r.status);return `<div class="page-heading editor-heading"><div><button class="back-link" data-act="runs">${icon('back')} 返回运行中心</button><h1>${esc(r.plan.name)}</h1><p class="mono">RUN-${r.id.slice(-8).toUpperCase()} · 前端模拟</p></div><div class="row">${active?button('取消执行','cancel-run','stop','','data-id="'+r.id+'"'):button('重新运行','rerun','refresh','','data-id="'+r.id+'"')}${button('演示复盘','replay','play','primary',`data-id="${r.id}" ${r.status==='done'?'':'disabled'}`)}</div></div><div class="panel"><div class="result-header"><div class="result-symbol">${icon(r.verdict==='pass'?'circle':r.status==='failed'?'alert':'monitor')}</div><div class="grow"><div class="row"><h2>运行${active?'进行中':'记录'}</h2>${runStatus(r)}<span class="muted" style="margin:0 6px">/</span>${verdict(r.verdict)}</div><p>${active?'正在模拟执行。可切换页面继续编辑其他方案。':r.status==='done'?'模拟执行已结束，可逐条查看行动结论与证据。':'当前执行已停止，详细原因请查看日志。'}</p></div><span class="mode-pill">模拟数据</span></div><div class="tabs">${[['overview','概览'],['judgement','行动判读'],['events','事件'],['files','产物'],['logs','日志']].map(([k,v])=>`<button data-act="result-tab" data-value="${k}" class="${ui.resultTab===k?'active':''}">${v}${k==='judgement'?` · ${r.results.length}`:''}</button>`).join('')}</div><div class="detail-content">${runTab(r)}</div></div>`;}
function runTab(r){
  if(ui.resultTab==='overview')return `<div class="summary-grid">${[['执行模式','前端模拟'],['仿真时长',`${duration(r.plan)} 秒`],['实体 / 行动',`${r.plan.entities.length} / ${r.plan.actions.length}`],['提交时间',formatTime(r.created)],['使用方案修订',`修订 ${r.plan.revision}`],['模拟情形',({success:'成功',missing:'事件缺失',review:'待复核',error:'运行失败'})[r.outcome]]].map(([k,v])=>`<div class="summary-cell"><label>${k}</label><b>${v}</b></div>`).join('')}</div><div style="margin:22px 0">${note('本次输入与配置已冻结。后续编辑方案不会改变这条运行记录。')}</div><h3 style="margin:24px 0 18px">执行时间线</h3><div class="timeline">${r.logs.map((log,i)=>`<div class="timeline-item"><b>${esc(log)}</b><small>STEP ${String(i+1).padStart(2,'0')}</small></div>`).join('')}</div>${r.review?note(`人工复核：${verdictMap[r.review.verdict][0]} · ${esc(r.review.note)}`):''}`;
  if(ui.resultTab==='logs')return `<div class="code-toolbar"><h3>运行日志</h3><button class="text-button" data-act="download-log" data-id="${r.id}">${icon('download')} 下载日志</button></div><pre>${esc(r.logs.map((l,i)=>`[${String(i+1).padStart(3,'0')}] ${l}`).join('\n'))}</pre>`;
  if(ui.resultTab==='files')return `${note('以下产物来自前端模拟。外部程序调用和真实文件目录写入将在后端接入后启用。')}<div style="margin-top:18px">${[['scenario','想定文件',`${r.files.ybnm}.json`],['commands','指令文件',`${r.files.ybnm}.json`],['events','模拟事件态势','模拟事件态势.ndjson'],['verdict','判读结果','verdict.json']].map(([k,name,f])=>`<div class="file-item">${icon('file')}<div class="grow"><b>${name}</b><p style="overflow-wrap:anywhere">${esc(f)}</p></div>${button('下载','run-download','download','small',`data-id="${r.id}" data-kind="${k}" ${['events','verdict'].includes(k)&&r.status!=='done'?'disabled':''}`)}</div>`).join('')}</div>`;
  if(!r.results.length)return empty('结果尚未生成',r.status==='failed'?'模拟运行失败，可在日志中查看原因。':'等待执行与产物收集完成后，结果会自动出现。');
  if(ui.resultTab==='events')return `${note('事件字段中的 action_id 为 Demo 专用关联标识，不代表真实仿真器的输出协议。')}<div class="timeline" style="margin-top:27px">${r.results.filter(x=>x.evidence).map(x=>`<div class="timeline-item"><b>${esc(x.executor)} → ${esc(x.target)}</b><p>${esc(x.evidence.message)}</p><small>T+${x.time}s · ${x.evidence.state}</small><pre style="margin-top:12px">${jsonHTML(x.evidence)}</pre></div>`).join('')||'<p class="muted">模拟情形中没有匹配事件。</p>'}</div>`;
  return `<div class="row between" style="margin-bottom:20px"><div><h3>逐行动判读</h3><p class="small muted" style="margin-top:7px">结论与运行状态分别保存，点击查看原始证据。</p></div>${button('人工备注','review','edit','small',`data-id="${r.id}"`)}</div><div class="table-scroll"><table><thead><tr><th>执行实体 / 行动</th><th>目标</th><th>对应事件</th><th>结论</th><th>证据</th></tr></thead><tbody>${r.results.map((x,i)=>`<tr><td><b style="font-weight:500">${esc(x.executor)}</b><p style="font-size:10px;margin-top:6px">${esc(x.name)} · ${esc(x.code||'000680')}</p></td><td>${esc(x.target)}</td><td>${x.evidence?'已发现':'未发现'}</td><td>${verdict(x.verdict)}</td><td><button class="text-button" data-act="evidence" data-id="${i}">${ui.evidence===i?'收起':'查看'} ${icon('down')}</button></td></tr>${ui.evidence===i?`<tr class="evidence-row"><td colspan="5"><p style="margin-bottom:12px;color:#8791a4">${esc(x.reason)}</p>${x.evidence?`<pre>${jsonHTML(x.evidence)}</pre>`:'<p class="muted">模拟事件记录中没有本条行动的匹配证据。</p>'}</td></tr>`:''}`).join('')}</tbody></table></div>${r.review?`<div style="margin-top:20px">${note(`人工复核：${verdictMap[r.review.verdict][0]} · ${esc(r.review.note)}。自动初判保持不变。`)}</div>`:''}`;
}
function libraryPage(){return `<div class="page-heading"><div><div class="eyebrow">MODEL & ACTION CATALOG</div><h1>模型与行动</h1><p>维护装备型号与行动类型，供想定编辑和行动构建使用。</p></div><div class="row">${chip(db.catalogMode==='backend'?'本地数据库':'本地回退',db.catalogMode==='backend'?'green':'amber')}${button('导入型号','import-models','upload')}${button('添加型号','add-model','plus','primary')}</div></div><div class="tabs" style="margin-bottom:25px;padding:0">${[['models','型号目录'],['actions','行动目录'],['judgements','判读规则']].map(([k,v])=>`<button data-act="library-tab" data-value="${k}" class="${ui.libraryTab===k?'active':''}">${v}</button>`).join('')}</div>${ui.libraryTab==='models'?modelCatalog():ui.libraryTab==='actions'?commandsUI.catalogHTML():`<div class="panel"><div class="panel-heading"><h2>判读规则状态</h2>${chip('待配置','amber')}</div><div class="panel-body">${note('当前示例没有给出行动代码与成功事件的完整对应关系。真实规则保持未配置；模拟运行可以注入结果，用于体验证据展示。')}<div style="margin-top:22px" class="summary-grid"><div class="summary-cell"><label>某报告事件</label><b class="mono">CMRE000000001</b></div><div class="summary-cell"><label>产生实体毁伤事件</label><b class="mono">CMRE000000003</b></div><div class="summary-cell"><label>默认行动结论</label>${verdict('review')}</div></div></div></div>`}`;}
function settingsPage(){const s=db.settings;return `<div class="page-heading"><div><div class="eyebrow">WORKSPACE SETTINGS</div><h1>设置</h1><p>保存路径与外部程序配置，为后续接入后端做准备。</p></div>${button('保存设置','save-settings','save','primary')}</div><div class="settings-grid"><div class="panel settings-panel"><h3>输入与产物目录</h3><div class="form-grid">${[['scenarioRoot','想定输入目录'],['commandRoot','指令输入目录'],['runsRoot','运行归档目录']].map(([k,v])=>field(v,`<input id="setting-${k}" value="${esc(s[k])}" aria-label="${v}">`,'','full')).join('')}</div><div class="form-section"><h3>外部程序</h3><div class="form-grid">${field('仿真器路径',`<input id="setting-simulator" value="${esc(s.simulator)}" placeholder="填写外部仿真器的可执行路径">`,'当前阶段只保存配置，不执行本机程序。','full')}${field('复盘程序路径',`<input id="setting-replay" value="${esc(s.replay)}" placeholder="填写外部复盘程序的可执行路径">`,'','full')}${field('运行超时 / 秒',`<input id="setting-timeout" type="number" min="1" step="1" value="${s.timeout}">`)}${field('并发执行数','<input disabled value="1 · 串行队列">')}</div></div><div class="row">${button('检查配置格式','check-settings','circle')}${button('导出配置','export-settings','download')}</div></div><aside class="stack"><div class="panel info-card" style="margin:0"><h3>${icon('monitor')} 当前连接模式</h3><p>${db.catalogMode==='backend'?'装备型号已连接本地 SQLite 数据库。':'装备型号当前使用浏览器回退目录。'}<br>方案、设置和模拟运行记录仍保存在浏览器。</p></div><div class="panel panel-body"><h3 style="margin-bottom:13px">后续接入</h3><p class="small muted" style="line-height:2">行动类型已入库，文件生成已接入后端校验。后续继续迁移方案、行动实例和真实运行。</p></div>${note('路径检查仅检查填写格式。当前浏览器无法验证路径是否存在。')}</aside></div>`;}

function render(){
  const focus=document.activeElement?.id,selection=document.activeElement?.selectionStart;
  db=api.snapshot();const r=route();
  app.innerHTML=shell();
  const body=r.page==='plan'?planPage(r):r.page==='runs'?runsPage():r.page==='run'?runPage(r.id):r.page==='library'?libraryPage():r.page==='settings'?settingsPage():plansPage();
  document.querySelector('#content').innerHTML=body;
  const selectAll=document.querySelector('#select-all');
  if(selectAll){const visible=filteredPlans(),selected=visible.filter(p=>ui.selected.has(p.id)).length;selectAll.checked=visible.length>0&&selected===visible.length;selectAll.indeterminate=selected>0&&selected<visible.length;}
  if(r.page==='plan'&&(!r.tab||r.tab==='map')&&ui.draft){
    mountMap(document.querySelector('#scenario-map'),{entities:clone(deployedEntities(ui.draft)),selected:ui.entity,placement:!!ui.placement,onSelect:id=>{ui.entity=id;render();},onPlace:(lon,lat)=>{const batch=createEntityBatch(ui.placement.model,ui.placement.side,deployedEntities(ui.draft).filter(e=>e.side===ui.placement.side).length+1,lon,lat,ui.placement.quantity,ui.placement.formation);ui.draft.entities.push(...batch);ui.entity=batch[0].id;ui.placement=null;touch();render();toast(`已批量创建 ${batch.length} 个${batch[0].bzlx?'编队':'普通实体'}。`);},onMove:e=>{const target=ui.draft.entities.find(x=>x.id===e.id);target.lon=e.lon;target.lat=e.lat;for(const child of mountedEntities(ui.draft,target.id)){child.lon=e.lon;child.lat=e.lat;}ui.entity=e.id;touch();render();}});
  }
  if(focus){const el=document.getElementById(focus);if(el){el.focus();try{el.setSelectionRange(selection,selection);}catch{}}}
}

// Dialogs keep temporary form state independent from live queue updates.
function newPlanDialog(example=false){showModal(example?'从示例创建':'新建方案',example?'复制一套可编辑的实体与行动配置。':'创建你的下一次仿真验证。',`<form id="new-plan-form"><div class="form-grid">${field('方案名称',`<input id="new-plan-name" required maxlength="60" placeholder="例如：基础行动验证" value="${example?'基础行动验证 · 新方案':''}">`,'','full')}${field('方案说明','<textarea id="new-plan-description" rows="3" placeholder="简要记录这次验证的目的（可选）"></textarea>','','full')}</div></form>`,button('取消','close')+'<button class="button primary" type="submit" form="new-plan-form">创建方案</button>');document.querySelector('#new-plan-form').onsubmit=async e=>{e.preventDefault();const name=document.querySelector('#new-plan-name').value.trim();if(!name)return modalError('请输入方案名称。');const description=document.querySelector('#new-plan-description').value;const p=await api.createPlan(name,example);p.description=description||p.description;await api.savePlan(p);closeModal();ui.draft=null;ui.dirty=false;go(`plan/${p.id}/${example?'map':'info'}`);toast('方案已创建。');};}
function entityDialog(preselectedParent=null){
  if(!ui.draft)return;
  const roots=deployedEntities(ui.draft),parent=roots.find(entity=>entity.id===preselectedParent),initialSide=parent?.side||'Blue';
  showModal('添加实体','机库和武器库是挂载关系；实际添加的是飞机或武器实体。',`<form id="entity-create"><div class="form-grid">${field('添加方式',`<select id="create-mode"><option value="map" ${parent?'':'selected'}>地图实体</option><option value="mount" ${parent?'selected':''}>挂载到已有实体</option></select>`)}${field('阵营',`<select id="create-side"><option value="Blue" ${initialSide==='Blue'?'selected':''}>蓝方</option><option value="Red" ${initialSide==='Red'?'selected':''}>红方</option></select>`)}${field('添加数量','<input id="create-count" type="number" min="1" max="50" step="1" value="1" required>','单次最多添加 50 个同类型实体。')}<div id="create-mount-options" class="form-grid full hidden">${field('所属主实体','<select id="create-parent" aria-label="所属主实体"></select>')}${field('挂载关系',`<select id="create-mount-kind" aria-label="挂载关系">${mountKinds.map(kind=>`<option value="${kind.id}">${mountOptionLabel(kind)}</option>`).join('')}</select>`,'<span id="create-relation-hint"></span>')}</div>${classificationFields.map(([,label],index)=>field(label,`<select id="create-category-${index}" data-create-category="${index}" aria-label="${label}"></select>`)).join('')}${field('装备模型','<select id="create-model" aria-label="装备模型"></select>','模型选择只显示名称；机库筛选飞机，武器库筛选武器。','full')}<label class="choice full" id="create-formation-wrap"><input id="create-formation" type="checkbox"><span><b>添加为编队</b><small>仅用于地图实体；未勾选时创建普通实体。</small></span></label></div><div style="margin-top:20px" id="create-note">${note('地图点击一次后，系统会围绕该位置自动排布所选数量的实体。')}</div></form>`,button('取消','close')+'<button class="button primary" id="create-submit" form="entity-create">开始批量布置</button>');
  const mounting=()=>document.querySelector('#create-mode').value==='mount';
  const selectedOwner=()=>roots.find(entity=>entity.id===document.querySelector('#create-parent').value);
  const syncCategories=()=>{const kind=document.querySelector('#create-mount-kind').value;let available=db.models.filter(model=>!mounting()||mountKindAcceptsModel(kind,model));for(const [index,[key]] of classificationFields.entries()){const select=document.querySelector(`#create-category-${index}`),current=select.value,values=[...new Set(available.map(model=>model[key]?.trim()||'未分类'))];select.innerHTML=values.map(value=>`<option value="${esc(value)}">${esc(value)}</option>`).join('');select.value=values.includes(current)?current:values[0]||'';available=available.filter(model=>(model[key]?.trim()||'未分类')===select.value);}const modelSelect=document.querySelector('#create-model'),currentModel=modelSelect.value;modelSelect.innerHTML=available.map(model=>`<option value="${esc(model.id)}">${esc(model.mxmc)}</option>`).join('');if(available.some(model=>model.id===currentModel))modelSelect.value=currentModel;modelSelect.disabled=!available.length;const relation=mountKinds.find(item=>item.id===kind);document.querySelector('#create-note').innerHTML=note(mounting()?`${relation.name}是挂载关系，本次将添加${relation.itemName}实体；挂载实体不单独显示地图标记。`:'地图点击一次后，系统会围绕该位置自动排布所选数量的实体。');};
  const syncParents=()=>{const side=document.querySelector('#create-side').value,select=document.querySelector('#create-parent'),current=select.value,available=roots.filter(entity=>entity.side===side);select.innerHTML=available.map(entity=>`<option value="${entity.id}">${esc(entity.name)}</option>`).join('');if(available.some(entity=>entity.id===(preselectedParent||current)))select.value=preselectedParent||current;const owner=selectedOwner(),kindSelect=document.querySelector('#create-mount-kind'),depotOption=kindSelect.querySelector('option[value="AmDp"]'),hasHang=!!owner&&mountedEntities(ui.draft,owner.id,'Hang').length>0;select.disabled=!available.length;kindSelect.disabled=!owner;depotOption.disabled=!hasHang;if(!hasHang&&kindSelect.value==='AmDp')kindSelect.value='ammo';document.querySelector('#create-relation-hint').textContent=hasHang?'已挂载机库，可向武器库添加武器。':'武器库需先为该主实体的机库添加飞机。';};
  const syncMode=()=>{const isMounting=mounting();document.querySelector('#create-mount-options').classList.toggle('hidden',!isMounting);document.querySelector('#create-formation-wrap').classList.toggle('hidden',isMounting);if(isMounting)document.querySelector('#create-formation').checked=false;document.querySelector('#create-submit').textContent=isMounting?'添加挂载实体':'开始批量布置';syncParents();syncCategories();};
  document.querySelectorAll('[data-create-category]').forEach(select=>select.onchange=syncCategories);document.querySelector('#create-side').onchange=()=>{syncParents();syncCategories();};document.querySelector('#create-parent').onchange=()=>{syncParents();syncCategories();};document.querySelector('#create-mount-kind').onchange=syncCategories;document.querySelector('#create-mode').onchange=syncMode;syncMode();
  document.querySelector('#entity-create').onsubmit=e=>{e.preventDefault();const quantity=Number(document.querySelector('#create-count').value),model=db.models.find(m=>m.id===document.querySelector('#create-model').value),isMounting=mounting();if(!Number.isSafeInteger(quantity)||quantity<1||quantity>50)return modalError('添加数量必须是 1 至 50 的整数。');if(!model)return modalError('当前分类下没有可用模型。');if(isMounting){const owner=selectedOwner(),kind=document.querySelector('#create-mount-kind').value,relation=mountKinds.find(item=>item.id===kind);if(!owner)return modalError('当前阵营没有可挂载的主实体。');if(kind==='AmDp'&&!mountedEntities(ui.draft,owner.id,'Hang').length)return modalError('请先为该主实体的机库添加飞机，再向武器库添加武器。');if(!mountKindAcceptsModel(kind,model))return modalError(`${relation.name}中只能添加${relation.itemName}实体。`);const start=mountedEntities(ui.draft,owner.id,kind).filter(entity=>entity.model.id===model.id).length+1,batch=createMountedEntityBatch(model,owner,start,quantity,kind);ui.draft.entities.push(...batch);ui.entity=batch[0].id;touch();closeModal();render();toast(`已向 ${owner.name} 的${relation.name}添加 ${batch.length} 个${relation.itemName}实体。`);return;}ui.placement={side:document.querySelector('#create-side').value,model,quantity,formation:document.querySelector('#create-formation').checked};closeModal();go(`plan/${ui.draft.id}/map`);render();};
}
function actionDialog(id=null){return commandsUI.dialog(id);}
async function runDialog(plans){
  const checks=plans.map(p=>({p,check:validate(p)})),valid=checks.filter(x=>!x.check.errors.length).map(x=>x.p);
  showModal('提交模拟运行','输入将冻结为运行快照，逐项进入串行队列。',`${note('此操作只启动前端模拟。下列情形用于验证交互，不代表真实仿真结果。')}<div style="margin:20px 0">${checks.map(({p,check})=>`<div class="file-item">${icon(check.errors.length?'alert':'circle')}<div class="grow"><b>${esc(p.name)}</b><p>${check.errors.length?esc(check.errors[0].message):`${p.entities.length} 实体 · ${p.actions.length} 行动 · 校验通过`}</p></div>${chip(check.errors.length?'跳过':'可运行',check.errors.length?'amber':'green')}</div>`).join('')}</div>${field('选择模拟情形','<select id="mock-outcome"><option value="review">待复核 · 未配置真实规则（默认）</option><option value="success">全部成功 · 生成模拟成功证据</option><option value="missing">事件缺失 · 第一条行动不通过</option><option value="error">运行失败 · 模拟异常退出</option></select>','仅影响本次模拟，不修改行动或真实规则。')}`,button('取消','close')+button(`提交可运行的 ${valid.length} 项`,'confirm-enqueue','play','primary',valid.length?'':'disabled'));
  document.querySelector('[data-act=confirm-enqueue]').onclick=async e=>{e.stopPropagation();e.currentTarget.disabled=true;try{const result=await api.enqueue(valid,document.querySelector('#mock-outcome').value);closeModal();ui.dirty=false;ui.resultTab='overview';go(valid.length===1?`run/${result[0].id}`:'runs');toast(`已提交 ${valid.length} 项模拟运行。`);}catch(err){modalError(err.message);e.currentTarget.disabled=false;}};
}
function modelDialog(){
  const defaults=['物资','海上','舰船','驱逐舰'],baseSuggestions=[['设施','物资'],['陆上','海上','空中'],['机场','车辆','舰船','飞机','导弹'],['无','驱逐舰','发射车','电子战飞机']];
  const suggestions=classificationFields.map(([key],index)=>[...new Set([...baseSuggestions[index],...db.models.map(model=>model[key]).filter(Boolean)])].sort((a,b)=>a.localeCompare(b,'zh-CN')));
  showModal('添加装备型号','一级至四级分类均可选择已有值，也可直接输入新分类；保存型号后，新分类会自动进入后续选择目录。',`<form id="model-form"><div class="form-grid">${classificationFields.map(([,label],index)=>field(label,`<input id="model-category-${index}" list="category-options-${index}" value="${defaults[index]}" required autocomplete="off"><datalist id="category-options-${index}">${suggestions[index].map(value=>`<option value="${esc(value)}"></option>`).join('')}</datalist>`)).join('')}${field('装备名称','<input id="model-name" required placeholder="例如：00驱逐舰">')}${field('型号编号','<input id="model-type" required placeholder="例如：00qzj">')}${field('模型编码','<input id="model-code" placeholder="留空时使用型号编号">','可选；没有独立编码时使用型号编号。','full')}${field('型号说明','<textarea id="model-desc" rows="2" placeholder="简单说明该型号的用途"></textarea>','','full')}</div></form>`,button('取消','close')+'<button class="button primary" form="model-form">添加型号</button>');
  document.querySelector('#model-form').onsubmit=async e=>{e.preventDefault();const name=document.querySelector('#model-name').value.trim(),type=document.querySelector('#model-type').value.trim(),code=document.querySelector('#model-code').value.trim()||type,categories=Object.fromEntries(classificationFields.map(([key],index)=>[key,document.querySelector(`#model-category-${index}`).value.trim()]));if(!name||!type||Object.values(categories).some(value=>!value))return modalError('装备名称、型号编号和四级分类均不能为空。');try{await api.addModel({id:type,mxmc:name,mxlx:type,mxnm:code,lxzymc:name,lxzynm:crypto.randomUUID(),bzlx:type,commandType:type,...categories,description:document.querySelector('#model-desc').value});closeModal();render();toast(`已添加型号 ${name}，新分类可在想定编辑中直接选择。`);}catch(err){modalError(err.message);}};
}
function replayDialog(id){const r=db.runs.find(r=>r.id===id);if(!r)return;showModal('演示复盘','前端模拟轨迹 · 外部复盘程序尚未接入',`${note('这是独立的交互示意：位置由初始坐标演示插值生成，不是外部仿真产物。')}<div id="replay-map" class="map-stage modal-map" style="margin-top:18px"></div><div class="replay-controls"><button class="button small" id="replay-toggle">${icon('play')} 播放</button><input type="range" id="replay-slider" min="0" max="100" value="0" aria-label="复盘时间"><span class="mono" id="replay-time">T+0s</span></div>`,button('关闭','close'),true);let progress=0,timer=null;const draw=()=>{const entities=clone(deployedEntities(r.plan));entities.forEach((e,i)=>{e.lon+=progress/100*(i%2?-.35:.5);e.lat+=progress/100*.15;});mountMap(document.querySelector('#replay-map'),{entities,readonly:true});document.querySelector('#replay-time').textContent=`T+${Math.round(progress/100*duration(r.plan))}s`;document.querySelector('#replay-slider').value=progress;};draw();document.querySelector('#replay-slider').oninput=e=>{progress=+e.target.value;draw();};document.querySelector('#replay-toggle').onclick=e=>{if(timer){clearInterval(timer);timer=null;e.currentTarget.innerHTML=icon('play')+' 播放';}else{e.currentTarget.innerHTML=icon('stop')+' 暂停';timer=setInterval(()=>{progress=progress>=100?0:progress+1;draw();},150);}};modalCleanup=()=>clearInterval(timer);}
function confirmLeave(path){showModal('保存当前修改','当前方案还有未保存的修改。','<p class="muted" style="line-height:1.9">保存后离开可保留实体位置、挂载和行动设置。</p>',button('取消','close')+button('放弃修改','discard-leave')+button('保存并离开','save-leave','save','primary'));document.querySelector('[data-act=discard-leave]').onclick=()=>{ui.dirty=false;ui.draft=null;closeModal();go(path);};document.querySelector('[data-act=save-leave]').onclick=async()=>{await saveDraft();closeModal();go(path);};}

async function act(action,el){const id=el?.dataset.id,value=el?.dataset.value;try{
  if(action==='close')return closeModal();
  if(['plans','runs','library','settings'].includes(action))return go(action);
  if(action==='new'||action==='example')return newPlanDialog(action==='example');
  if(action==='edit-plan')return go(`plan/${id}/map`);
  if(action==='copy-plan'){const p=await api.copyPlan(id);toast('副本已创建，实体和行动引用已重新生成。');return go(`plan/${p.id}/map`);}
  if(action==='archive'){await api.archivePlan(id);ui.selected.delete(id);return render();}
  if(action==='filter'){ui.filter=value;ui.selected.clear();return render();}
  if(action==='refresh'){render();return toast('已刷新本地数据。');}
  if(action==='editor-tab')return go(`plan/${ui.draft.id}/${value}`);
  if(action==='save'){await saveDraft();return toast('方案已保存。');}
  if(action==='add-entity')return entityDialog();
  if(action==='add-mount')return entityDialog(id);
  if(action==='stop-place'){ui.placement=null;return render();}
  if(action==='select-entity'){ui.entity=id;return render();}
  if(action==='delete-entity'){
    const p=ui.draft,children=mountedEntities(p,id),removeIds=new Set([id,...children.map(child=>child.id)]),related=p.actions.filter(a=>removeIds.has(a.executor)||a.targets.some(target=>removeIds.has(target))),entity=p.entities.find(item=>item.id===id);
    if(entity?.mountKind==='Hang'){
      const otherHang=mountedEntities(p,entity.parentId,'Hang').filter(item=>item.id!==entity.id),depotWeapons=mountedEntities(p,entity.parentId,'AmDp');
      if(!otherHang.length&&depotWeapons.length){showModal('暂不能删除机库飞机','武器库依赖机库关系。',`<p class="muted" style="line-height:1.9">请先删除武器库中的 ${depotWeapons.length} 个武器实体，再删除最后一个机库飞机。</p>`,button('知道了','close','check','primary'));return;}
    }
    showModal('删除实体',related.length||children.length?`同时影响 ${children.length} 个挂载和 ${related.length} 条关联行动。`:'此操作将从当前方案中移除实体。',`<p class="muted" style="line-height:1.9">${children.length?'所属挂载实体会一并删除。':''}${related.length?' 相关行动也会一并删除。':' 已有运行快照保持不变。'}</p>`,button('取消','close')+button(related.length||children.length?'确认删除':'删除实体','confirm-delete-entity','trash','danger'));
    document.querySelector('[data-act=confirm-delete-entity]').onclick=()=>{p.entities=p.entities.filter(item=>!removeIds.has(item.id));p.actions=p.actions.filter(a=>!related.includes(a));ui.entity=deployedEntities(p)[0]?.id||p.entities[0]?.id;touch();closeModal();render();toast(`${entity?.parentId?'挂载实体':'实体'}已删除。`);};return;
  }
  if(action==='add-action'||action==='edit-action')return actionDialog(action==='edit-action'?id:null);
  if(action==='copy-action'){const a=clone(ui.draft.actions.find(a=>a.id===id));a.id=uid('ACT_');ui.draft.actions.push(a);touch();render();return toast('行动已复制，请检查时间和库存分配。');}
  if(action==='delete-action'){ui.draft.actions=ui.draft.actions.filter(a=>a.id!==id);touch();return render();}
  if(action==='generate'){
    const check=validate(ui.draft);if(check.errors.length){go(`plan/${ui.draft.id}/files`);render();return toast(check.errors[0].message,true);}
    ui.draft=await api.generate(ui.draft);ui.dirty=false;go(`plan/${ui.draft.id}/files`);render();return toast('想定与指令已同时生成。');
  }
  if(action==='file-tab'){ui.fileTab=value;return render();}
  if(action==='locate-error'){if(id)ui.entity=id;go(`plan/${ui.draft.id}/${el.dataset.tab}`);return;}
  if(action==='export-file'){const f=ui.draft.generated;download(f[ui.fileTab],f.ybnm+'.json');return toast('已导出当前 JSON 文件。');}
  if(action==='export-pair'){const f=ui.draft.generated;download(makeZip({[`scenario/${f.ybnm}.json`]:JSON.stringify(f.scenario,null,2),[`command/${f.ybnm}.json`]:JSON.stringify(f.commands,null,2)}),f.ybnm+'.zip','application/zip');return toast('配套 ZIP 已导出，两份同名文件分目录保存。');}
  if(action==='run-current'){await saveDraft();return runDialog([ui.draft]);}
  if(action==='batch')return runDialog(db.plans.filter(p=>ui.selected.has(p.id)));
  if(action==='run-filter'){ui.runFilter=value;return render();}
  if(action==='run-detail'){ui.resultTab='overview';ui.evidence=null;return go(`run/${id}`);}
  if(action==='result-tab'){ui.resultTab=value;return render();}
  if(action==='cancel-run'){await api.cancel(id);return toast('模拟运行已取消。');}
  if(action==='rerun')return runDialog([db.runs.find(r=>r.id===id).plan]);
  if(action==='evidence'){ui.evidence=ui.evidence===+id?null:+id;return render();}
  if(action==='download-log'){download(db.runs.find(r=>r.id===id).logs.join('\n'),'run.log','text/plain');return;}
  if(action==='run-download'){const r=db.runs.find(r=>r.id===id),kind=el.dataset.kind;if(['scenario','commands'].includes(kind))download(r.files[kind],r.files.ybnm+'.json');else if(kind==='verdict')download({mock:true,run_id:r.id,verdict:r.verdict,results:r.results,review:r.review},'verdict.json');else download(r.results.filter(x=>x.evidence).map(x=>JSON.stringify({mock:true,eventList:[x.evidence]})).join('\n')+'\n','模拟事件态势.ndjson','application/x-ndjson');return;}
  if(action==='replay')return replayDialog(id);
  if(action==='review'){showModal('人工复核备注','自动初判保持不变，备注单独记录。',`<form id="review-form"><div class="form-grid">${field('人工结论','<select id="review-verdict"><option value="review">待复核</option><option value="pass">通过</option><option value="fail">不通过</option></select>','','full')}${field('复核说明','<textarea id="review-note" required rows="4" placeholder="说明你的判断依据…"></textarea>','','full')}</div></form>`,button('取消','close')+'<button class="button primary" form="review-form">保存备注</button>');document.querySelector('#review-form').onsubmit=async e=>{e.preventDefault();const n=document.querySelector('#review-note').value.trim();if(!n)return modalError('请填写复核说明。');await api.review(id,document.querySelector('#review-verdict').value,n);closeModal();render();toast('人工备注已保存。');};return;}
  if(action==='add-action-type')return commandsUI.typeDialog();
  if(action==='edit-action-type')return commandsUI.typeDialog(id);
  if(action==='library-tab'){ui.libraryTab=value;return render();}
  if(action==='add-model')return modelDialog();
  if(action==='model-detail'){const m=db.models.find(m=>m.id===id);showModal('模型配置',esc(m.mxmc)+' · 型号 '+esc(m.id),`<div class="summary-grid"><div class="summary-cell"><label>显示名称</label><b>${esc(m.mxmc)}</b></div><div class="summary-cell"><label>型号编号</label><b class="mono">${esc(m.id)}</b></div><div class="summary-cell"><label>模型编码</label><b class="mono">${esc(m.mxnm)}</b></div>${classificationFields.map(([key,label])=>`<div class="summary-cell"><label>${label}</label><b>${esc(m[key]||'未分类')}</b></div>`).join('')}<div class="summary-cell"><label>行动类型</label><b class="mono">${esc(m.commandType)}</b></div></div><p class="small muted" style="line-height:1.8;margin-top:18px">${esc(m.description||'可用于地图实体或挂载实体。')}</p>`,button('关闭','close')+button('导出模型配置','export-model','download','primary',`data-id="${esc(id)}"`));return;}
  if(action==='export-model'){download([db.models.find(m=>m.id===id)],'model-config.json');return;}
  if(action==='import-models'){const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{try{const text=await input.files[0].text();await api.importModels(JSON.parse(text));render();toast('模型配置已导入。');}catch(err){toast('导入失败：'+err.message,true);}};input.click();return;}
  if(action==='save-settings'||action==='check-settings'){
    const result={};for(const k of Object.keys(db.settings)){const el=document.querySelector('#setting-'+k);result[k]=k==='timeout'?Number(el.value):el.value.trim();}
    if(['scenarioRoot','commandRoot','runsRoot'].some(k=>!result[k])||!Number.isSafeInteger(result.timeout)||result.timeout<1)throw Error('请填写三个目录，并设置正整数超时时间。');
    if(result.scenarioRoot.replace(/[/\\]+$/,'')===result.commandRoot.replace(/[/\\]+$/,''))throw Error('想定与指令必须使用不同目录，以免同名文件覆盖。');
    if(action==='check-settings')return toast('填写格式正确。Demo 不检查本机路径是否存在。');await api.saveSettings(result);return toast('设置已保存到当前浏览器。');
  }
  if(action==='export-settings'){download(db.settings,'simtest-config.json');return;}
  if(action==='help')return showModal('探索 SimTest Demo','从方案创建到结果判读，体验一个完整的操作流程。',`<div class="stack">${note('所有运行和复盘轨迹都是模拟数据，未接入外部程序。')}<div><h3 style="margin-bottom:10px">建议体验顺序</h3><p class="muted" style="line-height:2.2">1. 打开「基础行动验证」，在地图上添加实体。<br>2. 在「模型与行动 → 行动目录」配置类型，再到「行动指令」填写参数、批量添加行动。<br>3. 生成两份 JSON，并导出配套 ZIP。<br>4. 模拟运行，选择成功或异常情形。<br>5. 在运行详情查看证据，并打开演示复盘。</p></div><p class="small muted" style="line-height:1.9">装备型号和行动类型保存在本地数据库，方案和模拟记录保存在当前浏览器。行动表单按类型展示必填字段，支持区域、航路、干扰、补给和策略配置；真实进程调用及外部复盘尚未接入。</p></div>`,button('开始探索','close','arrow','primary'));
}catch(err){toast(err.message||'操作未完成，请重试。',true);}}

document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav&&ui.dirty){e.preventDefault();go(nav.dataset.nav);return;}const el=e.target.closest('[data-act]');if(el)act(el.dataset.act,el);});
document.addEventListener('input',e=>{if(e.target.id==='plan-search'){ui.query=e.target.value;render();}});
document.addEventListener('change',e=>{
  const el=e.target;
  if(el.dataset.select){if(el.checked)ui.selected.add(el.dataset.select);else ui.selected.delete(el.dataset.select);render();}
  if(el.id==='select-all'){for(const p of filteredPlans())if(el.checked)ui.selected.add(p.id);else ui.selected.delete(p.id);render();}
  if(el.dataset.plan&&ui.draft){const key=el.dataset.plan;ui.draft[key]=['start','end'].includes(key)?el.value.replace('T',' ').padEnd(19,':00'):el.value;touch();render();}
  if(el.dataset.entityField&&ui.draft){const entity=ui.draft.entities.find(x=>x.id===ui.entity),key=el.dataset.entityField;entity[key]=['name','side'].includes(key)?el.value:el.value===''?NaN:Number(el.value);if(!entity.parentId&&['side','lon','lat','height'].includes(key))for(const child of mountedEntities(ui.draft,entity.id))child[key]=entity[key];touch();render();}
});
document.addEventListener('keydown',e=>{
  if(e.key==='Escape'){if(document.querySelector('.modal'))closeModal();else if(ui.placement){ui.placement=null;render();}}
  if((e.ctrlKey||e.metaKey)&&e.key==='s'&&ui.draft&&route().page==='plan'){e.preventDefault();saveDraft().then(()=>toast('方案已保存。'));}
  if(e.key==='Tab'&&document.querySelector('.modal')){const nodes=[...document.querySelectorAll('.modal button:not(:disabled),.modal input:not(:disabled),.modal select:not(:disabled),.modal textarea:not(:disabled)')].filter(el=>el.offsetParent!==null);if(!nodes.length)return;if(e.shiftKey&&document.activeElement===nodes[0]){e.preventDefault();nodes.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===nodes.at(-1)){e.preventDefault();nodes[0].focus();}}
});
window.addEventListener('beforeunload',e=>{if(ui.dirty){e.preventDefault();e.returnValue='';}});
window.addEventListener('hashchange',()=>{
  const next=location.hash,target=next.replace(/^#\/?/,'');
  const parts=target.split('/');
  if(ui.dirty&&ui.draft&&(parts[0]!=='plan'||parts[1]!==ui.draft.id)){
    history.replaceState(null,'',acceptedHash||`#/plan/${ui.draft.id}/map`);
    confirmLeave(target);return;
  }
  acceptedHash=next;ui.query='';render();
});
window.addEventListener('simtest:update',()=>{db=api.snapshot();if(!['plan','settings'].includes(route().page))render();});
const commandsUI=actionUI({api,getPlan:()=>ui.draft,getCatalog:()=>db.actionTypes||[],showModal,closeModal,modalError,esc,field,button,note,changed:dirty=>{if(dirty)touch();render();},toast});
async function bootstrap(){if(!location.hash)history.replaceState(null,'','#/plans');acceptedHash=location.hash;await Promise.all([api.initialize(),api.initializeActions()]);db=api.snapshot();render();}
bootstrap().catch(error=>{render();toast(error.message||'页面初始化失败。',true);});
